async function huntMore() {
  const targets = ["Giant rat", "Chicken", "Cow", "Zombie"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 30000);
      killed.push(target);
    }
  }
  return killed;
}

return await huntMore();

